+import { $internal } from '../common';
+import type { Schema } from '../storage';
+import type { Trait, TraitRecord, TraitValue } from '../trait/types';
+
+export const $aspect = Symbol('aspect');
+
+export type AspectTraits = readonly (Trait | Aspect)[];
+
+type Flatten<T extends readonly unknown[]> = T extends readonly [infer F, ...infer R]
+    ? F extends Aspect<infer A>
+        ? [...Flatten<A>, ...Flatten<R>]
+        : F extends Trait
+          ? [F, ...Flatten<R>]
+          : Flatten<R>
+    : [];
+
+type UnionToIntersection<U> = (U extends any ? (value: U) => void : never) extends (
+    value: infer I
+) => void
+    ? I
+    : never;
+
+type AspectRecord<T extends readonly Trait[]> = UnionToIntersection<TraitRecord<T[number]>>;
+
+export type Aspect<T extends readonly Trait[] = readonly Trait[]> = {
+    readonly [$aspect]: true;
+    readonly id: number;
+    readonly traits: T;
+    readonly schema: AspectRecord<T>;
+};
+
+let aspectId = 0;
+
+export function isAspect(value: unknown): value is Aspect {
+    return !!(value as Aspect | undefined)?.[$aspect];
+}
+
+export function createAspect<T extends AspectTraits>(...inputs: T): Aspect<Flatten<T>> {
+    if (inputs.length < 2) throw new Error('An aspect requires at least two traits.');
+
+    const traits: Trait[] = [];
+    for (const input of inputs) {
+        if (isAspect(input)) traits.push(...input.traits);
+        else traits.push(input as Trait);
+    }
+
+    if (traits.length < 2) throw new Error('An aspect requires at least two traits.');
+
+    const keys = new Set<string>();
+    const schema: Record<string, unknown> = {};
+    for (const trait of traits) {
+        if (!trait || typeof trait !== 'function' || !trait[$internal]) {
+            throw new Error('Aspect constituents must be traits.');
+        }
+        if (trait[$internal].relation) throw new Error('Relations cannot be aspect constituents.');
+
+        // AoS schemas do not expose their fields until an instance is created, so their
+        // values are treated as a single opaque constituent by the data helpers.
+        if (typeof trait.schema === 'function') continue;
+        for (const key of Object.keys(trait.schema as Schema)) {
+            if (keys.has(key)) throw new Error(`Aspect field '${key}' is declared more than once.`);
+            keys.add(key);
+            schema[key] = (trait.schema as Record<string, unknown>)[key];
+        }
+    }
+
+    return Object.freeze({
+        [$aspect]: true as const,
+        id: aspectId++,
+        traits: Object.freeze(traits.slice()) as unknown as Flatten<T>,
+        schema: Object.freeze(schema) as AspectRecord<Flatten<T>>,
+    });
+}
+
+export function splitAspectValue(aspect: Aspect, value: Record<string, any> | undefined) {
+    const values = new Map<Trait, TraitValue<any>>();
+    for (const trait of aspect.traits) {
+        if (trait[$internal].type === 'tag') continue;
+        if (typeof trait.schema === 'function') {
+            values.set(trait, value);
+            continue;
+        }
+        const partial: Record<string, any> = {};
+        for (const key of Object.keys(trait.schema)) {
+            if (value && key in value) partial[key] = value[key];
+        }
+        values.set(trait, partial);
+    }
+    return values;
+}
+
+export function mergeAspectValues(aspect: Aspect, get: (trait: Trait) => any): Record<string, any> {
+    const merged: Record<string, any> = {};
+    for (const trait of aspect.traits) {
+        if (trait[$internal].type === 'tag') continue;
+        Object.assign(merged, get(trait));
+    }
+    return merged;
+}
