+function createCallbackState(params: QueryParameter[], state: any[], traits: Trait[]) {
+    const result: any[] = [];
+    let cursor = 0;
+    for (const param of params) {
+        if (isAspect(param)) {
+            const values = mergeAspectValues(param, () => state[cursor++]);
+            // mergeAspectValues visits tags too; only advance for stored values.
+            cursor -= param.traits.filter((trait) => trait[$internal].type === 'tag').length;
+            result.push(values);
+        } else if (isModifier(param)) {
+            if (param.type === 'not') continue;
+            for (const trait of param.traits) if (trait[$internal].type !== 'tag') result.push(state[cursor++]);
+        } else if (isRelationPair(param)) {
+            const trait = param[$internal].relation[$internal].trait;
+            if (trait[$internal].type !== 'tag') result.push(state[cursor++]);
+        } else if ((param as Trait)[$internal].type !== 'tag') result.push(state[cursor++]);
+    }
+    return result;
